                        mask |= maska[(f ? 126 : 0) ^ ((1<<i)+(1<<j)+(1<<k))];
    return mask;
}

LL pot(LL a, LL w) {
    if (!w) return 1;
    LL b = pot(a, w/2);
    b = b * b % mod;
    if (w & 1) b = b * a % mod;
    return b;
}

